 const details={
  coding:["This portfolio is a useful example: the design, motion, and interactive demos are things I can iterate on in the browser with Codex and Claude Code. I can judge the actual behaviour instead of stopping at a static mockup.","I still describe myself as a product designer. Coding is expanding my range, especially for prototypes and interface details. I’m not claiming a separate engineering career or qualifications I haven’t listed."],
  'ai-workflow':["The useful part is the feedback loop: make something real, see what is awkward, and refine it. I use coding tools to shorten that loop; the decisions about clarity, hierarchy, and feel still need a designer.","The website is the practical result. It lets me explore motion, responsive layouts, and interaction rather than just describe what a developer should build."],
  website:["The case-study interactions and Everkind demos are good examples of why I wanted custom code. They make the work something you can interact with, not just a collection of images.","A lot of the iteration has been about feel: how the cards move, how a sheet opens, how type appears, and what needs to be simpler on mobile. Those details are part of the design work."],
  everkind:["The challenge was the first vision, not a refresh of an existing visual system. WhatsApp and ChatGPT were the only references to begin with. I worked through many iterations on V1, then V2 introduced journaling alongside conversation.","The case study shows V2. Journaling and the companion experience are two parts of the same app, and the interactive demos help show how those experiences behave. The app has over 200,000 downloads globally."],
  'everkind-process':["V1 started with conversation as the familiar foundation. The work was iterative because there wasn’t an established app direction to simply follow. The later V2 expanded the experience with journaling.","What you see in the case study is V2, not the very first idea. That distinction matters: the work evolved over many iterations rather than arriving as one finished concept."],
  trains:["The existing Amtrak-based flow wasn’t an ideal fit for UK commuters. The redesign brought outbound and return choices together, including direct routes, real-time fares, and SplitSave, within a four-week project.","The design question was how to help someone understand the whole journey. Seeing the two legs together gives those booking choices a clearer context."],
  risd:["The institution was rebranding, so the website needed to express that new identity. I worked across the homepage, Student Hub, and faculty profiles, with visual storytelling and craft at the centre.","The pages had different jobs. The homepage could express the institution’s creative identity, while Student Hub needed clear routes to resources. A shared visual language tied them together. The project received a W3 Gold Award."],
  craft:["For me, craft isn’t just a decorative layer at the end. Type size, spacing, hierarchy, colour, and motion all change how an interface reads and feels.","That comes from my visual-design background. Coding now gives me another way to refine those decisions in the actual medium, especially the things a static screen can’t show."],
  approach:["The starting point changes. Everkind needed a first vision; Melon needed clearer journey comparisons; RISD needed a rebrand translated into a digital experience. I don’t pretend every project followed the same process.","What stays consistent is making the idea tangible and judging the result. I care about whether people can understand the experience and whether the interface has been crafted well."],
  'working-style':["I like making the idea visible quickly enough that people can react to something concrete. Then I can spend the attention where it matters, rather than polishing an assumption forever.","Scrappy doesn’t mean careless. It means being willing to try a direction, change what isn’t working, and bring the final thing up to a level of craft I’m happy with."],
  motion:["This portfolio has been a place to try those ideas directly. When an effect feels awkward or heavy on mobile, it needs another pass. Motion should help the experience, not become something you have to put up with.","Coding makes that judgment more direct: I can look at the timing and interaction in the browser instead of only handing over a description."],
  skills:["The visual foundation is still there: typography, hierarchy, and interface craft. Product design adds the flows and structure; systems make the language repeatable; coding now lets me explore behaviour directly.","I’m strongest talking through the actual work. Everkind, Melon Trains, and RISD each show a different part of that range."]
 };
 Object.assign(details,{"current": ["At Absorb, design and code are part of the same conversation for me. I help product shape new features, and I use AI to support that work. Building an idea makes its behaviour easier to inspect and gives the product conversation something concrete to react to.", "My foundation is still product design: understanding what an experience needs to do, shaping the interface, and paying attention to craft. Coding adds another way to explore the idea. It lets me contribute beyond a static handoff without pretending that every problem is solved by generating more screens.", "The broader context is learning technology. Absorb’s products help companies upskill their people, and my role sits in that AI-powered ed-tech space. I can explain my role and approach, but I don’t make up feature announcements or share internal product plans."], "absorb-workflow": ["The value of coding in my design role is making the idea tangible. Instead of stopping at what something should look like, I can explore what happens when someone interacts with it. That helps me judge the design in its actual medium.", "AI is part of how I work on those explorations. The responsibility for the product direction and the quality of the design still needs judgment. I’m interested in using the tools to shape a better feature, not simply to produce more output.", "I bring the visual-design background, product-design experience, and growing coding ability together. That combination helps me move between shaping an idea with product and refining the interface details."], "labs": ["The problem was disconnected knowledge and workflows across corporate teams. The platform brought content creation, discovery, and connections between colleagues into one place. The goal was to make expertise useful beyond the team where it originally lived.", "AI-assisted categorisation helped organise contributions, while discovery by project, location, and skill helped people find relevant knowledge and colleagues. I designed the paths for creating, sharing, and discussing that content.", "The two-month project involved a Product Manager and an AI Researcher alongside my design work. The MVP established a direction for a white-label platform and secured development funding. I keep that outcome separate from claims about later adoption or revenue."], "umw": ["The starting point was a fragmented university website: navigation, content, and branding did not feel connected. I designed around the audiences who needed it, including prospective and current students, faculty, staff, and alumni.", "Campus storytelling and practical navigation needed to work together. Photography and layouts could communicate the university’s character, while the content structure helped someone move toward a programme or a useful next step.", "A programme finder supported exploration of more than 60 majors and programmes. A reusable component system in the WordPress Block Editor also gave editors building blocks for future pages, rather than leaving consistency to chance.", "The three-month project included a Project Manager and a front-end developer. The result was a more connected website and a repeatable foundation for updates. I don’t attach invented conversion numbers to it."], "ctrl": ["The starting question was what news might feel like through familiar social-feed patterns. I explored likes, reactions, comments, layouts, and typography as part of a visual direction for younger audiences.", "It was a one-week personal exploration. There wasn’t a client launch, research study, or usability test behind it. The value of the case study is the UI thinking and visual craft, not a claim that it changed engagement.", "I like having room for that kind of exploration alongside client work. CTRL let me try a different tone and interface language without turning it into a pretend product-success story."], "vista": ["Vista was a one-day UI exercise. Investment information was the subject matter, but the work was about visual hierarchy, colour, layouts, and portfolio screens.", "There was no user research or testing, and I don’t present it as professional finance experience. It belongs with my personal concepts: a place to explore how an interface could look and feel.", "That distinction matters to me. A concept can demonstrate craft without needing a made-up business result to justify it."], "pantrx": ["Pantrx connects meal planning to a shared view of groceries and pantry items. The problem is familiar: several people shopping or planning together can end up with duplicate purchases, missing items, or lists that disagree.", "I organised the concept around shared plans such as dinners and weekly preparation, rather than treating the shopping list as an isolated tool. Progress indicators and pantry alerts helped show what was ready and what needed attention.", "The proof of concept was a one-week exploration. It brought meal plans, shared lists, and pantry tracking into one mobile-first experience. I don’t claim launch metrics or tested improvements for it."], "georgia": ["For the Georgia Department of Agriculture, finding the right service was a major part of the design problem. The work connected programmes, regulations, registration, and the divisions responsible for them.", "The redesign included a clearer information architecture, a visual direction connected to Georgia’s identity, and more legible content. Forms and their structure also needed to support people completing tasks online.", "Reusable components helped the team keep layouts and interactions consistent as pages changed. The aim was a practical public-service website, not just a new coat of paint.", "The case study describes improved registration submissions and fewer phone enquiries. I discuss those directions without inventing percentages. The project ran for three months."], "flights": ["Flight search is a comparison problem. I brought the route, schedule, and price into a consistent result layout so the important pieces could be scanned together.", "Expanded flight details let a traveller inspect a journey while keeping the result context. Fare details then helped explain what an option included before moving into checkout.", "This is desktop SaaS work in Melon, separate from the train redesign. I can explain the design choices shown, but I don’t attach fabricated uplift or usability numbers to the project."], "checkout": ["The booking flow had several different jobs: traveller and loyalty information, seats and trip details, company policy, payment, and the final commitment. I gave those jobs defined places in the experience.", "Company-policy requirements needed to be visible when relevant, with a reason and supporting information for an out-of-policy trip. That is part of designing for business travel rather than only for a consumer purchase.", "The final review brought the trip together before booking. Afterwards, the trip page gave the itinerary and follow-up actions a place to live. The story extends beyond the payment moment.", "The case study shows the work itself. I haven’t supplied made-up completion-rate or revenue numbers for this redesign."], "qatar": ["This was work with SC.qa at Zoocha before the 2022 World Cup. The hospitality site needed to introduce Qatar to visitors and support the start of planning a stay.", "The official tournament branding gave the experience a strong visual foundation. I worked with typography, photography, and colour to connect that identity to destination content.", "The visitor story went beyond match day. Destination content and hospitality needed to feel part of the same experience as the event, rather than a separate brochure bolted onto it.", "I’m clear about how I describe it: client work with SC.qa at Zoocha, not a personal World Cup concept. I don’t invent booking results or claim responsibility for the tournament brand itself."]});
 const caseFacets={"everkind": {"role": "I designed Everkind’s first vision, starting with WhatsApp and ChatGPT as the only references. Many iterations shaped V1; V2 introduced journaling alongside conversation.", "result": "Everkind has over 200,000 downloads globally. That is the app’s reach, not proof of an isolated design change. The work shown is V2."}, "trains": {"role": "I redesigned Melon’s train-booking flow for UK commuters, bringing outbound and return fares into one comparison. The four-week project included real-time prices, direct routes, ticket types, and SplitSave.", "result": "The case study is about enabling train commuting for 4,000 customers. I focus on the clearer whole-journey comparison rather than adding new outcome numbers."}, "risd": {"role": "I designed the digital expression of RISD’s rebrand across its homepage, Student Hub, and faculty profiles. Visual storytelling, typography, and a shared design language were central.", "result": "The project received a W3 Gold Award. It connected RISD’s new identity with pages that served different needs, from introducing the institution to finding student resources."}, "labs": {"role": "I designed the knowledge-sharing platform alongside a Product Manager and an AI Researcher in a two-month project. Content creation, discovery, and connections between teams were the focus.", "result": "The MVP established a direction for the white-label platform and secured development funding. I don’t claim later product adoption or revenue results."}, "umw": {"role": "I worked on the university website’s visual direction, audience routes, programme discovery, and reusable components with a Project Manager and a front-end developer.", "result": "The result was a clearer, more connected university website and a component foundation for future updates. I don’t have a verified conversion percentage to quote."}, "ctrl": {"role": "CTRL was my one-week personal UI exploration of a social-style news experience. I designed the visual direction and screens.", "result": "This was a concept, not a launched or tested product. There are no engagement or usability results to claim."}, "vista": {"role": "Vista was a one-day personal UI exploration of investment screens, colour, hierarchy, and layouts.", "result": "It was not researched, tested, or presented as professional finance work. The outcome is the UI concept itself."}, "pantrx": {"role": "I designed the mobile-first proof of concept around shared meal plans, grocery lists, pantry tracking, and progress feedback.", "result": "It was a one-week concept exploration, with no verified launch metrics or test results."}, "georgia": {"role": "I worked on clearer service navigation, forms, content hierarchy, visual direction, and reusable components for the Georgia Department of Agriculture.", "result": "The case study describes more registration submissions and fewer phone enquiries. I don’t add unverified numerical improvements."}, "flights": {"role": "I redesigned Melon’s desktop flight results, expanded journey details, and fare information to support clearer comparisons.", "result": "The work shows a clearer comparison structure. I don’t have verified uplift numbers to add."}, "checkout": {"role": "I designed the checkout sequence covering traveller details, loyalty, trip and seats, policy, payment, review, and the post-booking itinerary.", "result": "The case study shows the redesigned flow. I don’t invent booking-completion or revenue improvements."}, "qatar": {"role": "I worked with SC.qa at Zoocha on a hospitality website before the 2022 World Cup, using official tournament branding with destination and trip-planning content.", "result": "The case study presents the design work, not a verified booking uplift. This was client work rather than a personal concept."}};
 const detailIndex=new Map();
 const lastChoice=new Map();
 function variation(kind,lastTopic=null){const options=boundaryReplies[kind];const previous=lastChoice.get(kind);let index=Math.floor(Math.random()*options.length);if(index===previous)index=(index+1+Math.floor(Math.random()*(options.length-1)))%options.length;lastChoice.set(kind,index);let text=options[index];if(kind==='offTopic'||kind==='insult'){const bridge=bridges[Math.floor(Math.random()*bridges.length)];text+='\n\n'+bridge}return result({kind,text})}
 function result(t){return {id:t.id||null,kind:t.kind||'fact',text:t.text,sources:(t.sources||[]).map(id=>sources[id]),links:t.links||[],suggestions:[]}}
 function reply(message,lastTopic=null){
  if(typeof message!=='string'||!message.trim())return result({kind:'offTopic',text:'A question would help. What would you like to know about me?'});
  if(message.length>600)return result({kind:'offTopic',text:'That’s a novella. Give me a shorter question about me and I’ll keep up.'});
  const raw=normalize(message);
  if(privateTopics.test(raw))return variation('privacy');
  const q=correct(raw);
  if(privateTopics.test(q))return variation('privacy');
  if(/\b(stupid|idiot|moron|dumb|ugly|trash|garbage|sucks?|loser|pathetic|talentless|useless|fuck|shit|bitch|asshole|offend|roast|insult)\b/.test(q))return variation('insult');
  if(/^(hi|hey|hello|hiya|yo|ola|oi)( vinny| there)?$/.test(q))return variation('greeting');
  if(/^(thanks|thank you|cheers|nice|cool|great|awesome)( vinny)?$/.test(q))return variation('thanks');
  const exact=topics.find(t=>normalize(labels[t.id])===q);if(exact)return result(exact);
  const prior=topics.find(t=>t.id===lastTopic);
  if(prior&&/^(more|tell me more|go on|and then|what else|how|why|how did you do that|what was the process|what about the process)$/.test(q)){const options=details[prior.id];if(options){const index=detailIndex.get(prior.id)||0;detailIndex.set(prior.id,index+1);return result({...prior,text:options[index%options.length]})}return result(topics.find(t=>t.id===prior.next[0])||prior);}
  const generic=new Set(['what','who','how','when','where','which','is','are','was','were','do','does','did','the','a','an','my','your','you','me','i','about','tell','can','could','would','please','vinny','his','he','work','design']);
  const words=q.split(' ').filter(w=>!generic.has(w));
  let best=null,bestScore=0;
  for(const t of topics){let score=0;for(const key of t.keys){const k=normalize(key);if((' '+q+' ').includes(' '+k+' '))score=Math.max(score,4+k.split(' ').length);else{const kw=k.split(' ').filter(w=>!generic.has(w));if(kw.length&&kw.every(w=>words.includes(w)))score=Math.max(score,2+kw.length)}}if(['intro','tools'].includes(t.id)&&score>0)score-=.5;if(score>bestScore){bestScore=score;best=t}}
  const facet=/\b(results?|outcomes?|impact|metrics|numbers|successful|success)\b/.test(q)?'result':/\b(role|contribution|responsibilities|what did you do|what did you design)\b/.test(q)?'role':null;
  const contextual=best&&caseFacets[best.id]?best:(!best||best.id==='ownership')&&prior&&caseFacets[prior.id]?prior:null;
  if(facet&&contextual)return result({...contextual,text:caseFacets[contextual.id][facet]});
  return best?result(best):variation('offTopic',lastTopic);
 }
 window.VinnyChat=Object.freeze({reply,topics:topics.map(t=>({id:t.id,label:labels[t.id]}))});
